WITH valid AS (SELECT *, SUBSTRING(account_type, 1, 2) AS account_type_prefix FROM accounts WHERE opened_date > DATE '2023-03-11') SELECT account_type, CASE WHEN balance >= 75000 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_tier, DATE_TRUNC('MONTH', opened_date) AS activity_month, AVG(balance) AS avg_balance, ROUND(AVG(balance), 2) AS avg_balance_2, SUM(balance) FILTER (WHERE status = 'FROZEN') AS frozen_total_balance, COUNT(CASE WHEN account_type = 'SAVINGS' THEN 1 END) AS savings_count FROM valid GROUP BY 1, 2, 3
